:root {
  --bg-card: #ffffff;
  --bg-header: #1a3c2e;
  --bg-sidebar: #f0f7f3;
  --bg-bird-item: #fafafa;
  --accent-green: #2e7d52;
  --accent-light: #6abf8a;
  --text-primary: #1a2e22;
  --text-secondary: #5a7566;
  --text-header: #ffffff;
  --text-sci: #8aab98;
  --rarity-common-bg: #e6f4ec;
  --rarity-common-text: #2e7d52;
  --rarity-uncommon-bg: #fff8e1;
  --rarity-uncommon-text: #b07d00;
  --rarity-rare-bg: #fce8e8;
  --rarity-rare-text: #c0392b;
  --border-color: #d4e8dc;
  --stat-highlight-bg: #2e7d52;
  --stat-highlight-text: #ffffff;
  --badge-bg: #3aaf6b;
  --badge-text: #ffffff;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.field-log {
  width: 490px;
  background: var(--bg-card);
  border-radius: 14px;
  overflow: hidden;
  border: 1.5px solid var(--border-color);
}

.log-header {
  background: var(--bg-header);
  padding: 10px 16px 8px;
}

.log-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 4px;
}

.log-date {
  font-size: 11px;
  font-weight: 500;
  color: var(--accent-light);
  letter-spacing: 0.04em;
}

.log-badge {
  font-size: 10px;
  font-weight: 700;
  background: var(--badge-bg);
  color: var(--badge-text);
  padding: 2px 8px;
  border-radius: 20px;
  letter-spacing: 0.03em;
}

.log-title {
  font-size: 18px;
  font-weight: 800;
  color: var(--text-header);
  line-height: 1.1;
  margin-bottom: 2px;
}

.log-location {
  font-size: 11px;
  color: var(--accent-light);
  font-weight: 400;
}

.log-body {
  display: grid;
  grid-template-columns: 1fr 164px;
  gap: 0;
}

.sightings {
  padding: 10px 12px 10px 16px;
  border-right: 1.5px solid var(--border-color);
}

.section-label {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
  margin-bottom: 6px;
}

.bird-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.bird-item {
  display: flex;
  align-items: center;
  gap: 6px;
  background: var(--bg-bird-item);
  border: 1px solid var(--border-color);
  border-radius: 7px;
  padding: 4px 7px;
}

.bird-emoji {
  font-size: 17px;
  line-height: 1;
  flex-shrink: 0;
}

.bird-info {
  display: flex;
  flex-direction: column;
  flex: 1;
  gap: 1px;
}

.bird-name {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.2;
}

.bird-sci {
  font-size: 9px;
  color: var(--text-sci);
  font-style: italic;
  line-height: 1.2;
}

.bird-meta {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
}

.bird-count {
  font-size: 11px;
  font-weight: 700;
  color: var(--accent-green);
}

.rarity {
  font-size: 8px;
  font-weight: 700;
  padding: 1px 5px;
  border-radius: 10px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.rarity.common {
  background: var(--rarity-common-bg);
  color: var(--rarity-common-text);
}

.rarity.uncommon {
  background: var(--rarity-uncommon-bg);
  color: var(--rarity-uncommon-text);
}

.rarity.rare {
  background: var(--rarity-rare-bg);
  color: var(--rarity-rare-text);
}

.log-sidebar {
  background: var(--bg-sidebar);
  padding: 10px 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.conditions {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.condition-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px;
}

.condition-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 4px 3px;
  gap: 1px;
}

.cond-icon {
  font-size: 13px;
  line-height: 1;
}

.cond-label {
  font-size: 8px;
  font-weight: 600;
  color: var(--text-secondary);
  text-align: center;
  line-height: 1.2;
}

.stats-row {
  display: flex;
  gap: 4px;
}

.stat-box {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 7px;
  padding: 5px 3px;
}

.stat-box.highlight-stat {
  background: var(--stat-highlight-bg);
  border-color: var(--stat-highlight-bg);
}

.stat-num {
  font-size: 16px;
  font-weight: 800;
  color: var(--accent-green);
  line-height: 1;
}

.highlight-stat .stat-num {
  color: var(--stat-highlight-text);
}

.stat-desc {
  font-size: 8px;
  font-weight: 600;
  color: var(--text-secondary);
  text-align: center;
  line-height: 1.3;
}

.highlight-stat .stat-desc {
  color: var(--stat-highlight-text);
  opacity: 0.85;
}

.observer-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 7px;
  padding: 5px 8px;
}

.observer-label {
  font-size: 9px;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.observer-name {
  font-size: 11px;
  font-weight: 700;
  color: var(--accent-green);
}
